query:
-- Lister tous les terroirs existants
SELECT id, terroir_id, name, country, region FROM terroirs ORDER BY name;

-- Compter les plantes sans liaison terroir
SELECT COUNT(*) as total_plants FROM plants;

-- Compter les plantes avec liaison terroir
SELECT COUNT(DISTINCT pt.plant_id) as linked_plants FROM plant_terroirs pt;

-- Lister les plantes sans liaison terroir (orphelines)
SELECT p.id, p.name, p.latin_name, p.origin, p.category
FROM plants p 
LEFT JOIN plant_terroirs pt ON p.id = pt.plant_id 
WHERE pt.id IS NULL 
ORDER BY p.name;

